using Epfo.Grievance.Application;
using Epfo.Grievance.Domain;
using Microsoft.AspNetCore.Identity;
using Microsoft.EntityFrameworkCore;
using Microsoft.Extensions.Configuration;
using Microsoft.IdentityModel.Tokens;
using System.IdentityModel.Tokens.Jwt;
using System.Security.Claims;
using System.Text;
using System.Text.RegularExpressions;

namespace Epfo.Grievance.Infrastructure;

public sealed class AuthService(EpfoDbContext db, IConfiguration configuration, IPasswordHasher<User> passwords) : IAuthService
{
    public async Task<LoginResponse?> LoginAsync(LoginRequest request, CancellationToken ct)
    {
        var user = await db.Users.Include(x => x.Office).Include(x => x.UserRoles).ThenInclude(x => x.Role).SingleOrDefaultAsync(x => x.Username == request.Username && x.IsEnabled, ct);
        if (user is null || passwords.VerifyHashedPassword(user, user.PasswordHash, request.Password) == PasswordVerificationResult.Failed) return null;
        var roles = user.UserRoles.Select(x => x.Role.RoleCode).ToArray(); if (!roles.Contains(request.Role, StringComparer.OrdinalIgnoreCase)) return null;
        return CreateSession(user, user.Office, roles);
    }
    public async Task<LoginResponse?> SwitchOfficeAsync(SwitchOfficeRequest request, AccessScope scope, CancellationToken ct)
    {
        if (!scope.IsSuperAdmin) throw new UnauthorizedAccessException("Only a Super Admin can switch office context.");
        var user = await db.Users.Include(x => x.Office).Include(x => x.UserRoles).ThenInclude(x => x.Role).SingleOrDefaultAsync(x => x.UserId == scope.UserId && x.IsEnabled, ct);
        var office = await db.Offices.SingleOrDefaultAsync(x => x.OfficeCode == request.OfficeCode && x.IsActive, ct);
        if (user is null || office is null) return null;
        return CreateSession(user, office, user.UserRoles.Select(x => x.Role.RoleCode).ToArray());
    }
    public async Task<IReadOnlyCollection<OfficeOption>> GetOfficesAsync(CancellationToken ct) => await db.Offices.Where(x => x.IsActive).OrderBy(x => x.OfficeName).Select(x => new OfficeOption(x.OfficeCode, x.OfficeName)).ToListAsync(ct);
    public async Task<UserResponse> SignUpAsync(SignUpRequest request, CancellationToken ct)
    {
        if (string.IsNullOrWhiteSpace(request.Username) || string.IsNullOrWhiteSpace(request.DisplayName) || string.IsNullOrWhiteSpace(request.Password) || request.Password.Length < 12) throw new ArgumentException("Username and display name are required; passwords must be at least 12 characters.");
        var office = await db.Offices.SingleOrDefaultAsync(x => x.OfficeCode == request.OfficeCode && x.IsActive, ct) ?? throw new ArgumentException("Unknown or inactive office.");
        if (await db.Users.AnyAsync(x => x.Username == request.Username || (request.Email != null && x.Email == request.Email), ct)) throw new InvalidOperationException("A user with that username or email already exists.");
        var user = new User { OfficeId = office.OfficeId, Office = office, Username = request.Username.Trim(), DisplayName = request.DisplayName.Trim(), Email = string.IsNullOrWhiteSpace(request.Email) ? null : request.Email.Trim(), PasswordHash = "", IsEnabled = false };
        user.PasswordHash = passwords.HashPassword(user, request.Password); db.Users.Add(user); await db.SaveChangesAsync(ct);
        return new UserResponse(user.UserId, user.Username, user.DisplayName, user.Email, office.OfficeCode, [], false);
    }
    private LoginResponse CreateSession(User user, Office office, IReadOnlyCollection<string> roles)
    {
        var key = configuration["Jwt:Key"] ?? throw new InvalidOperationException("Jwt:Key is not configured.");
        if (Encoding.UTF8.GetByteCount(key) < 32) throw new InvalidOperationException("Jwt:Key must contain at least 32 bytes for HS256.");
        var expiry = DateTime.UtcNow.AddHours(1);
        var identity = new ClaimsIdentity([new(ClaimTypes.NameIdentifier, user.UserId.ToString()), new(ClaimTypes.Name, user.Username), new("office_id", office.OfficeId.ToString()), new("office_code", office.OfficeCode), .. roles.Select(x => new Claim(ClaimTypes.Role, x))]);
        var token = new JwtSecurityToken(claims: identity.Claims, expires: expiry, issuer: configuration["Jwt:Issuer"], audience: configuration["Jwt:Audience"], signingCredentials: new SigningCredentials(new SymmetricSecurityKey(Encoding.UTF8.GetBytes(key)), SecurityAlgorithms.HmacSha256));
        return new(new JwtSecurityTokenHandler().WriteToken(token), expiry, user.Username, user.DisplayName, office.OfficeCode, office.OfficeName, roles);
    }
}

public sealed class CaseService(EpfoDbContext db) : ICaseService
{
    private static readonly Dictionary<string, string> Modules = new(StringComparer.OrdinalIgnoreCase) { ["jd-cell"]="JOINT_DECLARATION", ["telecalling"]="TELECALL", ["dcmc"]="DCMC_CLAIM", ["pension"]="PENSION", ["receipt"]="RECEIPT", ["thappal"]="THAPPAL", ["compliance"]="COMPLIANCE_INQUIRY", ["counter"]="COUNTER", ["whatsapp"]="WHATSAPP", ["apfc"]="APFC_REVIEW" };
    public async Task<IReadOnlyCollection<CaseListItem>> ListAsync(string module, string? search, AccessScope scope, CancellationToken ct) { var code=GetCode(module); EnsureModuleAccess(code,scope); IQueryable<GrievanceCase> query=db.Cases.Include(x=>x.CaseStatus).Include(x=>x.Attributes).Include(x=>x.CaseType).Where(x=>x.CaseType.TypeCode==code && x.OfficeId==scope.OfficeId); query=ApplySearch(query,search); return await query.OrderByDescending(x=>x.ReceivedAt).Take(250).Select(x=>new CaseListItem(x.ReferenceNumber,x.CaseStatus.StatusCode,x.ReceivedAt,ToFields(x))).ToListAsync(ct); }
    public async Task<IReadOnlyCollection<CaseListItem>> ReportAsync(string module, string? search, AccessScope scope, CancellationToken ct) { var code=GetCode(module); EnsureModuleAccess(code,scope); IQueryable<GrievanceCase> query=db.Cases.Include(x=>x.CaseStatus).Include(x=>x.Attributes).Where(x=>x.CaseType.TypeCode==code&&x.OfficeId==scope.OfficeId); query=ApplySearch(query,search); return await query.OrderByDescending(x=>x.ReceivedAt).Select(x=>new CaseListItem(x.ReferenceNumber,x.CaseStatus.StatusCode,x.ReceivedAt,ToFields(x))).ToListAsync(ct); }
    public async Task<CaseDetails?> GetAsync(string reference, AccessScope scope, CancellationToken ct) { var item=await db.Cases.Include(x=>x.CaseStatus).Include(x=>x.CaseType).Include(x=>x.Attributes).SingleOrDefaultAsync(x=>x.ReferenceNumber==reference&&x.OfficeId==scope.OfficeId,ct); return item is null||!CanAccess(item.CaseType.TypeCode,scope)?null:ToDetails(item); }
    public async Task<IReadOnlyCollection<CaseStatusHistoryItem>?> HistoryAsync(string reference, AccessScope scope, CancellationToken ct) { var item=await db.Cases.Include(x=>x.CaseType).SingleOrDefaultAsync(x=>x.ReferenceNumber==reference&&x.OfficeId==scope.OfficeId,ct); if(item is null||!CanAccess(item.CaseType.TypeCode,scope))return null; return await (from history in db.CaseStatusHistory join status in db.CaseStatuses on history.CaseStatusId equals status.CaseStatusId where history.CaseId==item.CaseId orderby history.ChangedAt descending select new CaseStatusHistoryItem(status.StatusCode,history.Remarks,history.ChangedAt)).ToListAsync(ct); }
    public async Task<CaseDetails> CreateAsync(string module, CreateCaseRequest request, AccessScope scope, CancellationToken ct) { var code=GetCode(module); EnsureModuleAccess(code,scope); ValidateFields(module,request.Fields); var type=await db.CaseTypes.SingleAsync(x=>x.TypeCode==code&&x.IsActive,ct); var status=await db.CaseStatuses.SingleAsync(x=>x.StatusCode=="NEW",ct); if (!await db.Offices.AnyAsync(x=>x.OfficeId==scope.OfficeId&&x.IsActive,ct)) throw new UnauthorizedAccessException("The assigned office is unavailable."); var fields=request.Fields; var item=new GrievanceCase { ReferenceNumber=$"EPFO-{DateTime.UtcNow:yyyyMMdd}-{Guid.NewGuid().ToString("N")[..6].ToUpperInvariant()}", OfficeId=scope.OfficeId, CaseTypeId=type.CaseTypeId, CaseStatusId=status.CaseStatusId, Uan=Get(fields,"uan"), MemberId=Get(fields,"member_id","memberid"), EstablishmentCode=Get(fields,"establishment_code","esttcode"), PpoNumber=Get(fields,"ppo_number","ppo"), MemberName=Get(fields,"member_name","pensioner_name","claimant_name","visitor_name","name"), MobileNumber=Get(fields,"mobile","mobile_number"), Email=Get(fields,"email"), Subject=Get(fields,"subject","message","issue_type"), Remarks=Get(fields,"remarks","rejection_reason"), ReceivedAt=DateTime.UtcNow, CreatedAt=DateTime.UtcNow, CreatedByUserId=scope.UserId, Attributes=fields.Where(x=>!Core.Contains(x.Key,StringComparer.OrdinalIgnoreCase)).Select(x=>new CaseAttribute { AttributeName=x.Key, AttributeValue=x.Value }).ToList() }; db.Cases.Add(item); await db.SaveChangesAsync(ct); db.CaseStatusHistory.Add(new CaseStatusHistory { CaseId=item.CaseId, CaseStatusId=status.CaseStatusId, ChangedByUserId=scope.UserId, ChangedAt=DateTime.UtcNow, Remarks="Case created" }); await db.SaveChangesAsync(ct); return ToDetails(item,status.StatusCode,module); }
    public async Task<DashboardSummary> GetDashboardSummaryAsync(AccessScope scope, CancellationToken ct) { var codes=AccessibleCodes(scope); var query=db.Cases.Where(x=>x.OfficeId==scope.OfficeId&&codes.Contains(x.CaseType.TypeCode)); var total=await query.CountAsync(ct); var open=await query.CountAsync(x=>!x.CaseStatus.IsClosed,ct); var modules=await query.Select(x=>x.CaseTypeId).Distinct().CountAsync(ct); return new DashboardSummary(total,open,modules); }
    public async Task<CaseDetails?> ChangeStatusAsync(string reference, ChangeCaseStatusRequest request, AccessScope scope, CancellationToken ct) { var item=await db.Cases.Include(x=>x.CaseStatus).Include(x=>x.CaseType).Include(x=>x.Attributes).SingleOrDefaultAsync(x=>x.ReferenceNumber==reference&&x.OfficeId==scope.OfficeId,ct); if(item is null||!CanAccess(item.CaseType.TypeCode,scope))return null; var status=await db.CaseStatuses.SingleAsync(x=>x.StatusCode==request.Status,ct); item.CaseStatusId=status.CaseStatusId; item.CaseStatus=status; item.ClosedAt=status.IsClosed?DateTime.UtcNow:null; db.CaseStatusHistory.Add(new CaseStatusHistory { CaseId=item.CaseId,CaseStatusId=status.CaseStatusId,ChangedByUserId=scope.UserId,ChangedAt=DateTime.UtcNow,Remarks=request.Remarks }); await db.SaveChangesAsync(ct); return ToDetails(item); }
    private static readonly string[] Core=["uan","member_id","memberid","establishment_code","esttcode","ppo_number","ppo","member_name","pensioner_name","claimant_name","visitor_name","name","mobile","mobile_number","email","subject","message","issue_type","remarks","rejection_reason"]; private static string GetCode(string module)=>Modules.TryGetValue(module,out var code)?code:throw new ArgumentException("Unknown module."); private static readonly Dictionary<string,string> ModuleRoles = new() { ["JOINT_DECLARATION"]="JDCELL", ["TELECALL"]="TELECALLING", ["DCMC_CLAIM"]="DCMC", ["PENSION"]="PENSION", ["RECEIPT"]="RECEIPT", ["THAPPAL"]="THAPPAL", ["COMPLIANCE_INQUIRY"]="COMPLIANCE", ["COUNTER"]="COUNTER", ["WHATSAPP"]="WHATSAPP", ["APFC_REVIEW"]="APFC" }; private static bool CanAccess(string code, AccessScope scope) => scope.IsSuperAdmin || scope.IsAdmin || (ModuleRoles.TryGetValue(code, out var role) && scope.Roles.Contains(role, StringComparer.OrdinalIgnoreCase)); private static void EnsureModuleAccess(string code, AccessScope scope) { if (!CanAccess(code, scope)) throw new UnauthorizedAccessException("You do not have permission to access this module."); } private static string[] AccessibleCodes(AccessScope scope) => (scope.IsSuperAdmin || scope.IsAdmin) ? ModuleRoles.Keys.ToArray() : ModuleRoles.Where(x=>scope.Roles.Contains(x.Value,StringComparer.OrdinalIgnoreCase)).Select(x=>x.Key).ToArray(); private static IQueryable<GrievanceCase> ApplySearch(IQueryable<GrievanceCase> query,string? search){if(string.IsNullOrWhiteSpace(search))return query;return query.Where(x=>x.ReferenceNumber.Contains(search)||(x.Uan!=null&&x.Uan.Contains(search))||(x.MemberId!=null&&x.MemberId.Contains(search))||(x.MobileNumber!=null&&x.MobileNumber.Contains(search))||(x.PpoNumber!=null&&x.PpoNumber.Contains(search))||(x.EstablishmentCode!=null&&x.EstablishmentCode.Contains(search))||(x.MemberName!=null&&x.MemberName.Contains(search))||(x.Subject!=null&&x.Subject.Contains(search))||x.Attributes.Any(a=>a.AttributeValue!=null&&a.AttributeValue.Contains(search)));} private static void ValidateFields(string module,Dictionary<string,string> fields){string Require(string key,string label)=>!string.IsNullOrWhiteSpace(Get(fields,key))?Get(fields,key)!:throw new ArgumentException($"{label} is required.");void Date(string key,string label){var value=Require(key,label);if(!DateOnly.TryParse(value,out _))throw new ArgumentException($"{label} must be a valid date.");}var uan=Get(fields,"uan");if(uan is not null&&!Regex.IsMatch(uan,@"^\d{12}$"))throw new ArgumentException("UAN must contain exactly 12 digits.");var mobile=Get(fields,"mobile","mobile_number");if(mobile is not null&&!Regex.IsMatch(mobile,@"^\d{10}$"))throw new ArgumentException("Mobile number must contain exactly 10 digits.");switch(module.ToLowerInvariant()){case "jd-cell":Require("uan","UAN");Require("member_id","Member ID");Require("remarks","Remarks");break;case "telecalling":Require("call_type","Call type");Require("mobile","Mobile number");Require("remarks","Remarks");break;case "compliance":Require("docket_kind","Register type");Require("establishment_code","Establishment code");Require("case_number","Case number");break;case "dcmc":Require("record_type","DCMC record type");Require("claimant_name","Claimant name");Date("seal_date","Seal date");Require("member_id","Member ID");Require("claim_status","Claim status");break;case "pension":Require("ppo_number","PPO number");Require("pensioner_name","Pensioner name");Date("entry_date","Entry date");break;case "receipt":Require("receipt_number","Receipt number");Require("sender","Received from");Date("received_date","Received date");Require("subject","Subject");break;case "thappal":Require("reference_number","Reference number");Require("sender","Sender");Date("received_date","Received date");Require("section_name","Section");Require("subject","Subject");break;case "counter":Require("visitor_name","Visitor name");Require("mobile","Mobile number");Require("issue_type","Issue type");Require("remarks","Remarks");break;case "whatsapp":Require("mobile","Mobile number");Require("category","Category");Require("message","Message summary");break;case "apfc":Require("source_module","Source module");Require("source_reference","Source reference");Require("review_outcome","Review outcome");Require("remarks","Review remarks");break;}} private static string? Get(Dictionary<string,string> f,params string[] keys)=>keys.Select(k=>f.GetValueOrDefault(k)).FirstOrDefault(v=>!string.IsNullOrWhiteSpace(v)); private static IReadOnlyDictionary<string,string?> ToFields(GrievanceCase x) { var fields=new Dictionary<string,string?>(StringComparer.OrdinalIgnoreCase) { ["uan"]=x.Uan, ["member_id"]=x.MemberId, ["establishment_code"]=x.EstablishmentCode, ["ppo_number"]=x.PpoNumber, ["member_name"]=x.MemberName, ["mobile"]=x.MobileNumber, ["email"]=x.Email, ["subject"]=x.Subject, ["remarks"]=x.Remarks }; foreach(var attribute in x.Attributes) fields[attribute.AttributeName]=attribute.AttributeValue; return fields; } private static CaseDetails ToDetails(GrievanceCase x,string? status=null,string? module=null)=>new(x.ReferenceNumber,module??Modules.FirstOrDefault(p=>p.Value==x.CaseType.TypeCode).Key,x.CaseStatus?.StatusCode??status??"NEW",x.ReceivedAt,ToFields(x));
}


